    writing-mode: sideways-rl;
    -webkit-transition: all 300ms linear 0ms;
    -khtml-transition: all 300ms linear 0ms;
    -moz-transition: all 300ms linear 0ms;
    -ms-transition: all 300ms linear 0ms;
    -o-transition: all 300ms linear 0ms;
    transition: all 300ms linear 0ms;
}

@media screen and (max-width: 1024px) {
    .ct-scroll-down .ct-scroll-down__link-text {
        writing-mode: initial;
    }
}

.ct-scroll-down .ct-scroll-down__icon {
    width: 80px;
    height: 80px;
    position: relative;
    display: inline-flex;
    align-items: center;
    justify-content: center;
}

.ct-scroll-down .ct-scroll-down__icon:before {
    content: "";
    position: absolute;
    inset: 0;
    border-radius: 80px;
    padding: 1px;
    background: linear-gradient(0deg, rgba(85, 181, 121, 0.5), rgba(38, 176, 207, 0.5));
    -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
    -webkit-mask-composite: xor;
    mask-composite: exclude;
    pointer-events: none;
}

.ct-scroll-down .ct-scroll-down__icon:after {
    content: "";
    position: absolute;
    width: 58px;
    height: 58px;
    border-radius: 50%;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    background: #fff;
    opacity: 0.05;
    filter: drop-shadow(0px 13px 69px rgba(84, 104, 133, 0.09));
}

.ct-scroll-down .ct-scroll-down__icon i {
    background: linear-gradient(90deg, #26b0cf 0%, #55b579 100%);
    background-clip: text;
    color: transparent;
    animation: pulse-icon-scroll-down 2.5s cubic-bezier(0.4, 0, 0.2, 1) infinite;
}

@keyframes pulse-icon-scroll-down {
    0%,
    100% {
        transform: translateY(-4px) rotate(90deg) scale(1);
    }
    50% {
        transform: translateY(4px) rotate(90deg) scale(1.05);
    }
}

.ct-social-text .ct-social-text__item {
    display: flex;
    align-items: center;
    flex-direction: column;
    gap: 50px;
}

@media screen and (max-width: 1024px) {
    .ct-social-text .ct-social-text__item {
        gap: 20px;
    }
}

.ct-social-text span {
    font-family: Unbounded;
    font-size: 16px;
    font-weight: 400;
    letter-spacing: 1.6px;
    text-transform: uppercase;
    writing-mode: sideways-lr;
    background: linear-gradient(180deg, #55b579 0%, #26b0cf 100%);
    background-clip: text;
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
}

.ct-social-text i {
    background: linear-gradient(180deg, #55b579 0%, #26b0cf 100%);
    background-clip: text;
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
}

/* ── TABLE ──────────────────────────────────── */
.tbl {
    width: 100%;
    border-collapse: collapse;
    font-size: 13px;
}

.tbl th {
    background: #F8F9FA;
    color: #6B7280;
    font-size: 11px;
    font-weight: 600;
    letter-spacing: .06em;
    text-transform: uppercase;
    padding: 10px 14px;
    border-bottom: 1px solid #E5E7EB;
    text-align: left;
    white-space: nowrap;
}

.tbl td {
    padding: 14px 16px;
    border-bottom: 1px solid #F0F2F5;
    color: #374151;
    vertical-align: middle;
    background: #fff;
}

.tbl tr:nth-child(even) td {
    background: #FCFDFE;
}

.tbl tr:hover td {
    background: #F6FAF8;
}

.tbl tr td:first-child {
    border-top-left-radius: 10px;
    border-bottom-left-radius: 10px;
}

.tbl tr td:last-child {
    border-top-right-radius: 10px;
    border-bottom-right-radius: 10px;
}

.tbl tr:last-child td {
    border-bottom: none;
}

/* ── FORM FIELD ─────────────────────────────── */
.form-input {
    width: 100%;
    padding: 10px 14px;
    border: 1px solid #E5E7EB;
    border-radius: 8px;
    font-size: 14px;
    font-family: inherit;
    outline: none;
    color: #111827;
    transition: border-color .2s;
}

.form-input:focus {
    border-color: #2ECC71;
}

.form-input:disabled {
    background: #F9FAFB;
    color: #9CA3AF;
}